196		var canceledIDs []int64
197		var sawTrigger bool
198		for _, r := range e.Records() {
199			if r.Kind == RecordRiskTriggered {
200				sawTrigger = true
201				continue
202			}
203			if sawTrigger && r.Kind == RecordCanceled {
204				canceledIDs = append(canceledIDs, r.OrderID)
205				if r.RiskDay != 1 || r.RiskLoss != 90 || r.RiskLimit != 90 || !r.RiskRestrict {
