232		}
233		rj := e.Records()[recsBefore]
234		if rj.Kind != RecordRejected || rj.RiskLoss != 90 || rj.RiskLimit != 90 ||
235			!rj.RiskRestrict || rj.RiskDay != 1 {
236			t.Fatalf("触线拒单记录风险快照错误: %+v", rj)
