546			t.Fatalf("整批回滚后最新报价应停留在 seq1@5: %+v", q)
547		}
548		if !e.HasGap("A") {
549			t.Fatal("整批回滚后 seq3 应仍在等待")
550		}
551		if st := e.RiskStatus(); st.Equity != 10 || st.Loss != 0 {
552			t.Fatalf("整批回滚不得改变净值: %+v", st)
553		}
554	}
555	
556	func TestRiskOverflowFillRejectedAndTradeIDReusable(t *testing.T) {
557		e, _ := NewEngine(math.MaxInt64 - 5)
558		mustSetMax(t, e, "A", 10)
559		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 1}, 1)
560		id := mustBuy(t, e, "A", 1, 1)
561		if _, err := e.Fill(Trade{TradeID: 1, OrderID: id, Symbol: "A", Side: Buy, Price: 1, Qty: 1}); err != nil {
562			t.Fatal(err)
563		}
564		cash := e.Cash() // MaxInt64-6
565		if err := e.StartTradingDay(1, 100); err != nil {
566			t.Fatal(err)
567		}
568	
569		sid := mustSell(t, e, "A", 1, 1)
570		// 成交价 10：现金 +10 溢出 int64，整笔拒绝。
571		_, err := e.Fill(Trade{TradeID: 7, OrderID: sid, Symbol: "A", Side: Sell, Price: 10, Qty: 1})
572		if !errors.Is(err, ErrInt64Overflow) {
573			t.Fatalf("成交致现金溢出必须返回 ErrInt64Overflow，实际 %v", err)
574		}
575		if e.Cash() != cash || e.Position("A") != 1 {
576			t.Fatalf("溢出成交不得记账: cash=%d pos=%d", e.Cash(), e.Position("A"))
577		}
578		if o, _ := e.Order(sid); o.Status != StatusPending || o.Remaining() != 1 {
579			t.Fatalf("溢出成交后卖单应保持有效: %+v", o)
580		}
581		// 编号未被占用：修正价格后同编号可成功。
582		if _, err := e.Fill(Trade{TradeID: 7, OrderID: sid, Symbol: "A", Side: Sell, Price: 1, Qty: 1}); err != nil {
583			t.Fatalf("被溢出拒绝的成交编号应可复用: %v", err)
584		}
585		if e.Position("A") != 0 {
586			t.Fatalf("修正后成交应正常入账: pos=%d", e.Position("A"))
587		}
588	}
589	
590	func TestRiskRecordsAreImmutableAcrossChanges(t *testing.T) {
591		e := setupHolding(t, 10) // cash 900, pos A 10
592		if err := e.StartTradingDay(1, 90); err != nil {
593			t.Fatal(err)
594		}
595		mustBuy(t, e, "A", 2, 9) // 触线时应被撤销
596		mustQuote(t, e, "A", Quote{Seq: 2, Moment: 2, Price: 1}, 1)
597		rec := lastRiskRecord(t, e)
598		if rec.RiskEquity != 910 || rec.RiskLoss != 90 {
599			t.Fatalf("前置触线快照错误: %+v", rec)
600		}
601	
602		// Records() 返回深拷贝：篡改副本不得影响内部记录。
603		recs := e.Records()
604		for i := range recs {
605			if recs[i].Kind == RecordRiskTriggered {
606				recs[i].RiskQuoteRefs[0].Price = 999
607				recs[i].RiskLoss = 1
608			}
609		}
610		again := lastRiskRecord(t, e)
611		if again.RiskQuoteRefs[0].Price != 1 || again.RiskLoss != 90 {
612			t.Fatalf("内部触线记录不得被外部副本改写: %+v", again)
613		}
614	
615		// 后续行情、跨日不得改写旧记录。
616		mustQuote(t, e, "A", Quote{Seq: 3, Moment: 3, Price: 100}, 1)
617		if err := e.StartTradingDay(2, 100); err != nil {
618			t.Fatal(err)
619		}
620		again = lastRiskRecord(t, e)
621		if again.RiskDay != 1 || again.RiskLoss != 90 || again.RiskLimit != 90 ||
622			again.RiskQuoteRefs[0].Price != 1 {
623			t.Fatalf("跨日与行情不得改写旧触线记录: %+v", again)
624		}
625	}
626	
627	func TestRiskSellTradeRealizesLossAndTriggers(t *testing.T) {
628		e, _ := NewEngine(1000)
629		mustSetMax(t, e, "A", 100)
630		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 100}, 1)
631		bid := mustBuy(t, e, "A", 10, 100)
632		if _, err := e.Fill(Trade{TradeID: 1, OrderID: bid, Symbol: "A", Side: Buy, Price: 100, Qty: 10}); err != nil {
633			t.Fatal(err)
634		}
635		if err := e.StartTradingDay(1, 50); err != nil {
636			t.Fatal(err)
637		}
638		// 浮亏 40 尚未触线。
639		mustQuote(t, e, "A", Quote{Seq: 2, Moment: 2, Price: 96}, 1)
640		if e.RiskStatus().Loss != 40 || e.RiskStatus().Restricted {
641			t.Fatalf("浮亏 40 不应触线: %+v", e.RiskStatus())
642		}
643		// 以 95 卖出全部持仓：现金 950、空仓，实现亏损 50，卖单成交触发触线。
644		sid := mustSell(t, e, "A", 10, 90)
645		if _, err := e.Fill(Trade{TradeID: 2, OrderID: sid, Symbol: "A", Side: Sell, Price: 95, Qty: 10}); err != nil {
646			t.Fatal(err)
647		}
648		st := e.RiskStatus()
649		if !st.Restricted || st.Equity != 950 || st.Loss != 50 {
650			t.Fatalf("卖单实现亏损应触发触线: %+v", st)
651		}
652		rec := lastRiskRecord(t, e)
653		if rec.RiskTrigger != RiskTriggerTrade || rec.RiskRefSeq != 2 || len(rec.RiskQuoteRefs) != 0 {
654			t.Fatalf("空仓后触线记录应关联成交且无持仓报价: %+v", rec)
655		}
656	}
657	
658	func lastRiskRecord(t *testing.T, e *Engine) Record {
659		t.Helper()
660		for i := len(e.records) - 1; i >= 0; i-- {
661			if e.records[i].Kind == RecordRiskTriggered {
662				return e.records[i]
663			}
664		}
665		t.Fatal("不存在触线记录")
666		return Record{}
667	}
668	
669	func countRiskRecords(e *Engine) int {
670		n := 0
671		for _, r := range e.Records() {
672			if r.Kind == RecordRiskTriggered {
673				n++
674			}
675		}
676		return n
677	}
