551		if _, err := e.Fill(Trade{TradeID: 2, OrderID: sid, Symbol: "A", Side: Sell, Price: 10, Qty: 2}); err != nil {
552			t.Fatalf("缺口时已有卖单应能成交: %v", err)
553		}
554		extra := mustSell(t, e, "A", 2, 10)
555		if err := e.Cancel(extra); err != nil {
556			t.Fatalf("缺口时撤单应可处理: %v", err)
557		}
558		if e.Position("A") != 8 {
559			t.Fatalf("缺口期间卖出成交后持仓应为 8，实际 %d", e.Position("A"))
560		}
561	}
562	
563	func TestSellFillCashOverflowRejectedWithoutRiskOpen(t *testing.T) {
564		// 未开启交易日、未设置金额上限：卖出所得加回现金后溢出 int64 也必须整笔拒绝。
565		e, _ := NewEngine(math.MaxInt64 - 5)
566		mustSetMax(t, e, "A", 10)
567		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 1}, 1)
568		bid := mustBuy(t, e, "A", 1, 1)
569		if _, err := e.Fill(Trade{TradeID: 1, OrderID: bid, Symbol: "A", Side: Buy, Price: 1, Qty: 1}); err != nil {
570			t.Fatal(err)
571		}
572		cash := e.Cash() // MaxInt64-6
573		sid := mustSell(t, e, "A", 1, 1)
574		before := len(e.Records())
575	
576		// 成交金额 10 本身未溢出，但加回现金后无法表示：整笔拒绝。
577		res, err := e.Fill(Trade{TradeID: 7, OrderID: sid, Symbol: "A", Side: Sell, Price: 10, Qty: 1})
578		if !errors.Is(err, ErrInt64Overflow) {
579			t.Fatalf("卖出现金溢出必须返回 ErrInt64Overflow，实际 %v", err)
580		}
581		if res != (FillResult{}) {
582			t.Fatalf("溢出拒绝必须返回零值成交结果，实际 %+v", res)
583		}
584		if e.Cash() != cash || e.Position("A") != 1 || e.Sellable("A") != 0 {
585			t.Fatalf("溢出成交不得改变资金与持仓: cash=%d pos=%d sellable=%d",
586				e.Cash(), e.Position("A"), e.Sellable("A"))
587		}
588		o, _ := e.Order(sid)
589		if o.Status != StatusPending || o.Remaining() != 1 {
590			t.Fatalf("卖单占用不得提前释放: %+v", o)
591		}
592	
593		// 只追加一条拒绝记录，且固化成交要素与当时的报价、持仓限额快照。
594		recs := e.Records()
595		if len(recs) != before+1 {
596			t.Fatalf("只能追加一条拒绝记录，实际新增 %d 条", len(recs)-before)
597		}
598		rec := recs[len(recs)-1]
599		if rec.Kind != RecordRejected || rec.TradeID != 7 || rec.OrderID != sid ||
600			rec.Symbol != "A" || rec.Side != Sell || rec.TradePrice != 10 || rec.Qty != 1 {
601			t.Fatalf("拒绝记录要素错误: %+v", rec)
602		}
603		if !strings.Contains(rec.Reason, "超出") {
604			t.Fatalf("拒绝原因应说明加回现金后超出范围: %q", rec.Reason)
605		}
606		if !rec.QuoteValid || rec.QuoteSeq != 1 || rec.QuotePrice != 1 {
607			t.Fatalf("拒绝记录缺少报价快照: %+v", rec)
608		}
609		if !rec.MaxPositionValid || rec.MaxPosition != 10 {
610			t.Fatalf("拒绝记录缺少持仓限额快照: %+v", rec)
611		}
612	
613		// 编号未被占用：修正价格后同编号可成交；现金恰好到达 MaxInt64 允许。
614		res, err = e.Fill(Trade{TradeID: 7, OrderID: sid, Symbol: "A", Side: Sell, Price: 6, Qty: 1})
615		if err != nil {
616			t.Fatalf("被溢出拒绝的成交编号应可复用: %v", err)
617		}
618		if e.Cash() != math.MaxInt64 || e.Position("A") != 0 {
619			t.Fatalf("修正后成交应正常入账: cash=%d pos=%d", e.Cash(), e.Position("A"))
620		}
621		if res.Status != StatusFilled || res.Filled != 1 || res.Remaining != 0 {
622			t.Fatalf("修正后成交结果错误: %+v", res)
623		}
624		// 已入账成交幂等重放：返回原结果，不因余额变化重新结算。
625		again, err := e.Fill(Trade{TradeID: 7, OrderID: sid, Symbol: "A", Side: Sell, Price: 6, Qty: 1})
626		if err != nil || again != res {
627			t.Fatalf("幂等重放应返回原结果: %+v, %v", again, err)
628		}
629		if e.Cash() != math.MaxInt64 {
630			t.Fatalf("幂等重放不得再次记账: cash=%d", e.Cash())
631		}
632	}
633	
634	func TestSellFillCashOverflowPartialFillKept(t *testing.T) {
635		// 部分成交后的卖单遇到现金溢出：只拒绝本次成交，已入账部分保留。
636		e, _ := NewEngine(math.MaxInt64 - 12)
637		mustSetMax(t, e, "A", 10)
638		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 1}, 1)
639		bid := mustBuy(t, e, "A", 2, 1)
640		if _, err := e.Fill(Trade{TradeID: 1, OrderID: bid, Symbol: "A", Side: Buy, Price: 1, Qty: 2}); err != nil {
641			t.Fatal(err)
642		}
643		sid := mustSell(t, e, "A", 2, 1)
644		if _, err := e.Fill(Trade{TradeID: 2, OrderID: sid, Symbol: "A", Side: Sell, Price: 5, Qty: 1}); err != nil {
645			t.Fatal(err)
646		}
647		cash := e.Cash() // MaxInt64-9
648	
649		if _, err := e.Fill(Trade{TradeID: 3, OrderID: sid, Symbol: "A", Side: Sell, Price: 10, Qty: 1}); !errors.Is(err, ErrInt64Overflow) {
650			t.Fatalf("第二笔卖出现金溢出必须拒绝，实际 %v", err)
651		}
652		if e.Cash() != cash || e.Position("A") != 1 {
653			t.Fatalf("之前入账的现金与持仓必须保留: cash=%d pos=%d", e.Cash(), e.Position("A"))
654		}
655		o, _ := e.Order(sid)
656		if o.Filled != 1 || o.Remaining() != 1 || o.Status != StatusPartial {
657			t.Fatalf("卖单累计成交量与剩余量必须保留: %+v", o)
658		}
659		// 修正后同编号成交：按实际成交金额入账。
660		if _, err := e.Fill(Trade{TradeID: 3, OrderID: sid, Symbol: "A", Side: Sell, Price: 9, Qty: 1}); err != nil {
661			t.Fatalf("修正后同编号成交应成功: %v", err)
662		}
663		if e.Cash() != math.MaxInt64 || e.Position("A") != 0 {
664			t.Fatalf("修正后成交应正常入账: cash=%d pos=%d", e.Cash(), e.Position("A"))
665		}
666	}
