	}
	if len(e2.Records()) != before+1 || e2.ReservedCash() != 20 {
		t.Fatalf("溢出后只加一条拒绝且占用不变: records=%d reserved=%d",
			len(e2.Records())-before, e2.ReservedCash())
	}
}

