	}

	// 现金足够（2），但持仓合计 M+1 超出 int64：整笔拒绝。
	before := len(e.Records())
	id, err := e.Buy("A", 2, 1)
	if !errors.Is(err, ErrInt64Overflow) {
		t.Fatalf("合计超出 int64 必须返回包装 ErrInt64Overflow 的错误，实际 %v", err)
	}
	if id != 0 {
		t.Fatalf("溢出拒绝必须返回零订单编号，实际 %d", id)
	}
	expectErr(t, err, "委托被拒绝")

